import React from "react";
import DialogFeaturesTitle from "src/views/dialog/IT-Solution-Features/DialogFeaturesTitle";
import TableFeaturesTitle from "src/views/tables/IT-Solution-Features/TableFeaturesTitle";
import { useEffect, useState, useRef, useCallback } from "react";
import { Button, Grid, MenuItem, Select, Typography } from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useParams } from "react-router-dom";
import DialogOverviewMainTitle from "src/views/dialog/IT-Solution-Overview/DialogOverviewMainTitle";
import TableOverviewMainTitle from "src/views/tables/IT-Solution-Overview/TableOverviewMainTitle";
import DialogOverviewDownload from "src/views/dialog/IT-Solution-Overview/DialogOverviewDownload";

const ITSolutionOverviewTitle = () => {
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [featureTitle, setFeatureTitle] = useState([]);
  const [pdfData, setPdfData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("active");

  // Testimonials
  const [featureTitleDialogOpen, setFeatureTitleDialogOpen] = useState(false);
  const [featureTitleDialogMode, setFeatureTitleDialogMode] = useState("add");
  const [featureTitleToEdit, setFeatureTitleToEdit] = useState(null);
  const [uploadPdfDialogOpen, setUploadPdfDialogOpen] = useState(false);
  const [uploadPdfDialogMode, setUploadPdfDialogMode] = useState("add");
  const [uploadPdfToEdit, setUploadPdfToEdit] = useState(null);
  const [diableAddTitle, setDiableAddTitle] = useState(false);
  const [uploadPdfButtonVisible, setUploadPdfButtonVisible] = useState(true);
  const [deletePdfButtonVisible, setDeletePdfButtonVisible] = useState(false);
  const { id } = useParams();

  const toggleFeatureTitleFormDialog = (
    e,
    mode = "add",
    featureTitleToEdit = null
  ) => {
    setFeatureTitleDialogOpen((prev) => !prev);
    setFeatureTitleDialogMode(mode);
    setFeatureTitleToEdit(featureTitleToEdit);
  };
  const toggleUploadPdfFormDialog = (
    e,
    mode = "add",
    featureTitleToEdit = null
  ) => {
    setUploadPdfDialogOpen((prev) => !prev);
    setUploadPdfDialogMode(mode);
    setUploadPdfToEdit(featureTitleToEdit);
  };
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [featureTitleToDelete, setFeatureTitleToDelete] = useState(null);
  const [deleteType, setDeleteType] = useState("");

  const toggleConfirmationDialog = (e, deletetype, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setFeatureTitleToDelete(dataToDelete);
    setDeleteType(deletetype);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewMainTitle.list(id), { params })
      .then((response) => {
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setDiableAddTitle(true);
        } else {
          setDiableAddTitle(false); // Enable the button if there is no data
        }

        setFeatureTitle(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchPdfData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewDownload.list(id))
      .then((response) => {
        const responseData = response.data.data;
        setPdfData(responseData);
        if (responseData) {
          setUploadPdfButtonVisible(false);
          setDeletePdfButtonVisible(true);
        }
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
    fetchPdfData();
  }, [currentPage, pageSize, search, status]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      const deleteUrl =
        deleteType === "delete details"
          ? ApiEndPoints.ITSolutionOverviewMainTitle.delete(
              featureTitleToDelete.id
            )
          : ApiEndPoints.ITSolutionOverviewDownload.delete(
              featureTitleToDelete.id
            );
      axiosInstance
        .delete(deleteUrl)
        .then((response) => response.data)
        .then((response) => {
          deleteType === "delete details"
            ? fetchData({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              })
            : fetchPdfData();
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, featureTitleToDelete, pageSize, search, deleteType]
  );
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Overview Main Title " />
            </Typography>
          }
          action={
            <Button
              variant="contained"
              disabled={diableAddTitle}
              onClick={toggleFeatureTitleFormDialog}
            >
              Add Details
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box sx={{ p: 5 }}>
              <TableOverviewMainTitle
                search={search}
                loading={loading}
                rows={featureTitle}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleFeatureTitleFormDialog}
                toggleUploadPdf={toggleUploadPdfFormDialog}
                uploadPdfButtonVisible={uploadPdfButtonVisible}
                deletePdfButtonVisible={deletePdfButtonVisible}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogOverviewMainTitle
        mode={featureTitleDialogMode}
        open={featureTitleDialogOpen}
        toggle={toggleFeatureTitleFormDialog}
        dataToEdit={featureTitleToEdit}
        itSolutionId={id}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogOverviewDownload
        mode={uploadPdfDialogMode}
        open={uploadPdfDialogOpen}
        toggle={toggleUploadPdfFormDialog}
        dataToEdit={uploadPdfToEdit}
        itSolutionId={id}
        onSuccess={() => {
          fetchPdfData();
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title={
          deleteType === "delete details" ? "Delete Details" : "Delete PDF"
        }
        subtitle={
          deleteType === "delete details"
            ? "Are you sure you want to delete this Details?"
            : "Are you sure you want to delete this PDF?"
        }
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionOverviewTitle;
